def transform(grid):
 h=len(grid);w=len(grid[0]);out=[r[:] for r in grid]
 seeds=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==8]
 for r,c in seeds:
  rays=[]
  for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
   path=[];a,b=r+dr,c+dc
   while 0<=a<h and 0<=b<w:
    if grid[a][b]!=0:
     if grid[a][b]!=8:rays.append((len(path),path,a,b))
     break
    path.append((a,b));a+=dr;b+=dc
  if not rays:continue
  _,path,a,b=min(rays,key=lambda x:x[0])
  for x,y in path:out[x][y]=8
  color=grid[a][b]
  for x in range(h):
   for y in range(w):
    if grid[x][y]==color:
     for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
      u,v=x+dx,y+dy
      if 0<=u<h and 0<=v<w and grid[u][v]==0:out[u][v]=8
 return out

